use std::env;
use std::process::Command;
use std::fs;

fn main() {
    let script_path = env::var("SCRIPT_PATH").expect("SCRIPT_PATH not set");
    // Ensure the script file exists and is readable
    let _ = fs::read_to_string(&script_path).expect("Failed to read script file");
    let output = Command::new("stryke")
        .arg(&script_path)
        .output()
        .expect("Failed to execute strykelang CLI");
    if !output.status.success() {
        panic!("stryke exited with non-zero status");
    }
    let stdout = String::from_utf8_lossy(&output.stdout);
    // Escape backslashes and double quotes for JSON string safety
    let escaped = stdout.replace('\\', "\\\\").replace('"', "\\\"");
    println!("{{\"result\":\"{}\"}}", escaped);
}
